def solve_sequence():
    n_target = 2025
    memo = {1: 0}

    def a(n):
        if n in memo:
            return memo[n]

        if n % 2 == 0:
            # n = 2k, k = n/2
            k = n // 2
            # a_2k = 2*a_k + k
            result = 2 * a(k) + k
        else:
            # n = 2k + 1, k = (n-1)/2
            k = (n - 1) // 2
            # a_{2k+1} = a_k + a_{k+1} + k
            result = a(k) + a(k + 1) + k

        memo[n] = result
        return result

    return a(n_target)

print(solve_sequence())

def calculate_a(N):
    if N <= 0:
        return None

    # Initialize DP table (1-indexed)
    a = {1: 0}

    for n in range(2, N + 1):
        if n % 2 == 0:
            # n = 2k => k = n/2
            k = n // 2
            if k not in a:
                # This should not happen if we iterate sequentially, but good practice
                raise ValueError(f"a_{k} required but not calculated before a_{n}")
            a[n] = 2 * a[k] + k
        else:
            # n = 2k + 1 => k = (n-1)/2
            k = (n - 1) // 2
            k_plus_1 = k + 1

            if k not in a or k_plus_1 not in a:
                raise ValueError(f"a_{k} or a_{k+1} required but not calculated before a_{n}")

            a[n] = a[k] + a[k_plus_1] + k

    return a[N]

N_target = 2025
result = calculate_a(N_target)
print(f"a_{N_target} = {result}")
